// Normalise the form payload into one clean object, and keep every binary
// (the photos) attached so the next node can write them to disk.

const form = $('QR Form').first().json;
const ticketId = $input.first().json.ticket_id;

const severityMap = {
  "It breaks a show — need this now": "Show-stopper",
  "Needs fixing before it's used again": "Fix before next use",
  "Annoying but it still works": "Annoying but working",
  "Just putting it on the record": "Note for the record"
};

const binary = $('QR Form').first().binary || {};
const photoKeys = Object.keys(binary);

return [{
  json: {
    ticket_id: ticketId,
    submitter_name: (form['Your Name'] || '').trim(),
    // Contact details are deliberately not collected - the name is enough,
    // and a repair ticket is no place to accumulate crew phone numbers.
    submitter_email: null,
    submitter_phone: null,
    raw_venue: form['Venue'] || null,
    venue: form['Venue'] || null,
    raw_description: (form["What's the problem?"] || '').trim(),
    gear_item: (form['What gear?'] || '').trim() || null,
    troubleshooting: (form['What have you already tried?'] || '').trim() || null,
    submitter_severity: severityMap[form['How bad is it?']] || null,
    photo_count: photoKeys.length,
    photo_keys: photoKeys,
    submitted_at: new Date().toISOString()
  },
  binary
}];

