// Move the staged photos into their ticket folder now that the ticket row
// exists, and emit one item per photo for Record Photos.

const fs = require('fs');
const path = require('path');

const st = $('Stage Photos').first().json;
const ticketId = $('Normalise').first().json.ticket_id;

if (!st.staged || !st.staged.length) {
  return [{ json: { ticket_id: ticketId, seq: 0, no_photos: true } }];
}

const dir = path.join('/opt/gear-tickets/photos', ticketId);
fs.mkdirSync(dir, { recursive: true });

const out = [];
for (const s of st.staged) {
  const dst = path.join(dir, s.filename);
  try {
    fs.renameSync(path.join(st.stage_dir, s.filename), dst);
  } catch (e) {
    // A photo that won't move must not cost us the ticket.
    out.push({ json: { ticket_id: ticketId, seq: 0, no_photos: true,
                       photo_error: `${s.filename}: ${e.message}` } });
    continue;
  }
  out.push({
    json: {
      ticket_id: ticketId,
      seq: s.seq,
      filename: s.filename,
      stored_path: dst,
      public_url: `https://tickets.tinydoorstudios.com/p/${ticketId}/${s.filename}`,
      mime_type: s.mime_type,
      bytes: s.bytes
    }
  });
}

try { fs.rmdirSync(st.stage_dir); } catch (e) {}

return out;

