// Parse the triage response defensively. A bad model reply must never lose a ticket.

const base = $('Normalise').first().json;
const photos = $('Save Photos to Disk').all()
  .filter(p => !p.json.no_photos)
  .map(p => p.json.public_url);

const VALID_CAT = ['Damaged Gear','Missing Gear','Showfile Issue','Venue / Facility','Vehicle','Supplies / Restock','Other'];
const VALID_SEV = ['Show-stopper','Fix before next use','Annoying but working','Note for the record'];

let ai = {};
try {
  const raw = $input.first().json;
  const content = raw?.choices?.[0]?.message?.content ?? raw?.content ?? '';
  ai = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  ai = {};
}

const clean = s => (typeof s === 'string' && s.trim()) ? s.trim() : null;

const fallbackTitle = `${base.venue || 'Unknown venue'} — ${(base.gear_item || base.raw_description || 'ticket').slice(0, 70)}`;

const category = VALID_CAT.includes(ai.category) ? ai.category : 'Other';
const severity = VALID_SEV.includes(ai.severity)
  ? ai.severity
  : (base.submitter_severity || 'Fix before next use');

return [{
  json: {
    ...base,
    title: clean(ai.title)?.slice(0, 90) || fallbackTitle,
    category,
    severity,
    gear_item: clean(ai.gear_item) || base.gear_item,
    troubleshooting: base.troubleshooting,
    duplicate_of: clean(ai.duplicate_of),
    triage_notes: clean(ai.notes),
    triage_model: $env.TRIAGE_MODEL || 'unknown',
    triage_ok: Object.keys(ai).length > 0,
    photo_urls: photos,
    photo_count: photos.length
  }
}];

