parameters.blocksUi:
={{ (() => {
  const t = $('Apply Triage').first().json;
  // Monday may have failed - the post still goes out, and it has to say so.
  const m = $('Create Monday Item').first().json?.data?.create_item ?? null;
  const icon = { 'Show-stopper': ':rotating_light:', 'Fix before next use': ':wrench:', 'Annoying but working': ':warning:', 'Note for the record': ':memo:' }[t.severity] || ':inbox_tray:';
  const photos = (t.photo_urls || []);
  // The model's note is already a one-line summary; fall back to the raw report.
  const summary = t.triage_notes || (t.raw_description || '').slice(0, 240);
  const heading = m && m.url ? `*<${m.url}|${t.title}>*` : `*${t.title}*`;
  const facts = [t.ticket_id, t.venue, t.category, t.gear_item, `by ${t.submitter_name}`]
    .filter(Boolean).join(' · ');
  const blocks = [
    { type: 'header', text: { type: 'plain_text', text: `${icon} ${String(t.severity).toUpperCase()}`, emoji: true } },
    { type: 'section', text: { type: 'mrkdwn', text: `${heading}\n${summary}` } },
    { type: 'context', elements: [ { type: 'mrkdwn', text: facts } ] }
  ];
  if (t.troubleshooting) {
    blocks.push({ type: 'context', elements: [ { type: 'mrkdwn', text: `:mag: Already tried: ${t.troubleshooting.slice(0, 300)}` } ] });
  }
  if (photos.length) {
    // Block-kit messages do NOT unfurl links, so a bare URL shows as text and
    // nothing else - an image block is the only way to actually see the photo
    // in the channel. Slack does its own downscaling of the full-size original.
    blocks.push({ type: 'image', image_url: photos[0], alt_text: t.title || 'ticket photo' });
    blocks.push({ type: 'context', elements: [ { type: 'mrkdwn', text: photos.map((u,i) => `<${u}|Photo ${i+1} (full size)>`).join('  ·  ') } ] });
  }
  if (t.duplicate_of) {
    blocks.push({ type: 'context', elements: [ { type: 'mrkdwn', text: `:link: Might be a duplicate of *${t.duplicate_of}*` } ] });
  }
  if (!m) {
    blocks.push({ type: 'context', elements: [ { type: 'mrkdwn', text: ':warning: Monday did not accept this one - it is in Postgres only. Add it to the board by hand.' } ] });
  }
  return JSON.stringify({ blocks });
})() }}

parameters.jsCode:
// Photos land here FIRST, straight off the form trigger, because this is the
// only node in the chain whose *input* still carries binary data.
// helpers.getBinaryDataBuffer reads from the current node's input, and every
// other candidate (getBinaryStream, getBinaryPath) is blocked in the Code
// sandbox. Ticket ID doesn't exist yet, so files go to a staging dir keyed by
// execution id and get moved into place once the ticket row is written.
// Staging deliberately sits OUTSIDE /opt/gear-tickets/photos so nginx never
// serves a half-finished ticket.

const fs = require('fs');
const path = require('path');

const binary = $input.first().binary || {};
const keys = Object.keys(binary);
const stageDir = path.join('/opt/gear-tickets/staging', String($execution.id));
const staged = [];

if (keys.length) {
  fs.mkdirSync(stageDir, { recursive: true });
  let seq = 0;
  for (const key of keys) {
    seq += 1;
    const b = binary[key];
    const ext = (b.fileExtension || 'jpg').replace(/^\./, '');
    const filename = `${seq}.${ext}`;
    const buf = await this.helpers.getBinaryDataBuffer(0, key);
    fs.writeFileSync(path.join(stageDir, filename), buf);
    staged.push({ seq, filename, mime_type: b.mimeType || null, bytes: buf.length });
  }
}

// One item out, always - the next node is a Postgres query that must run once.
return [{ json: { stage_dir: stageDir, staged } }];
